mapper.update:
UPDATE route
SET route_name = #{routeName}, depart_port = #{departPort}, arrive_port = #{arrivePort},
    duration = #{duration}, description = #{description}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM route
WHERE deleted = 0 AND depart_port = #{departPort} AND arrive_port = #{arrivePort}
  AND route_name = #{routeName}
AND id != #{excludeId}
